```python
def encode_token(last_id: int) -> str:
    return sign(base64.urlsafe_b64encode(json.dumps({"after": last_id}).encode()))

def decode_token(token: str) -> int:
    payload = verify(token)  # raises BadToken if signature or shape is wrong
    return int(json.loads(base64.urlsafe_b64decode(payload))["after"])
```

My new code, api/search.py:

```python
def search_books():
    q = request.args.get("q", "")
    token = request.args.get("page_token")
    after = 0
    if token:
        after = json.loads(base64.urlsafe_b64decode(token))["after"]
    cur.execute(
        f"SELECT id, title, author FROM books WHERE title ILIKE '%{q}%' AND id > {after} ORDER BY id LIMIT 25"
    )
    rows = cur.fetchall()
    next_token = base64.urlsafe_b64encode(json.dumps({"after": rows[-1][0]}).encode()).decode() if rows else None
    return jsonify({"items": rows, "next": next_token})
```

