const { trace } = require("../lib/trace");
const { saveGuestStay, notifyHousekeeping } = require("../services/stays");

router.post("/webhooks/checkin", verifySignature, async (req, res) => {
  trace(req);
  const ev = req.body;
  const stay = await saveGuestStay({
    reservationId: ev.reservation_id,
    guestName: ev.guest.name,
    passport: ev.guest.passport_no,
    room: ev.room,
    nights: ev.nights,
  });
  await notifyHousekeeping(stay.room);

  if (!ev.reservation_id || !ev.room || !Number.isInteger(ev.nights) || ev.nights < 1) {
    return res.status(400).json({ error: "invalid event" });
  }
  res.status(201).json({ ok: true });
});
```

